import app from 'flarum/admin/app';
export default async function loadAsset(name) {
  const URL = `${app.forum.attribute('assetsBaseUrl')}/extensions/fof-discussion-language/${name}`;
  const response = await fetch(URL);
  if (!response.ok) {
    if (response.status === 404) {
      throw new Error(`Missing asset (\`${name}\`): ${URL}`);
    }
  }
  return await response.json();
}
flarum.reg.add('fof-discussion-language', 'admin/utils/loadAsset', loadAsset);